      function getPlaygroundSkillIconConfig(iconId) {
        return PLAYGROUND_SKILL_ICON_OPTIONS.find((option) => option.id === getPlaygroundSkillIconId(iconId))
          || PLAYGROUND_SKILL_ICON_OPTIONS[0];
      }

