            kind: getTraceEventKindClass(log.type),
            source: log.source,
            type: log.type,
            timestamp: readTraceTimestamp(log.record),
            title: log.title,
            copy: log.copy,
            createdAt: log.createdAt,
            durationMs: getTraceEventDurationMs(log.record),
            raw: log.raw,
            tokenCount: getTraceEventTokens(log.record),
