        function handleSelectSchedule(scheduleId) {
          if (!scheduleId) return;
          const scheduleRecord = schedulesById[scheduleId] || null;
          if (!scheduleRecord) return;
          openScheduleEditor(scheduleRecord);
        }

        function getScheduleDraftValidationError(scheduleRecord) {
          const normalizedSchedule = normalizePlaygroundScheduleRecord(scheduleRecord || buildProjectScheduleDraft(selectedProject));
          const trimmedTask = String(normalizedSchedule.task || normalizedSchedule.name || "").trim();
          const normalizedType = normalizedSchedule.scheduleType === "recurring" ? "recurring" : "one-time";
          const selectedAgent = agentsById[String(normalizedSchedule.agentId || "").trim()] || null;
          const selectedEnvironment = availableBacklogEnvironments.find((environment) => environment.id === String(normalizedSchedule.environmentId || "").trim()) || null;

          if (!trimmedTask) return "Please enter a task.";
          if (!selectedAgent) return "Please choose an agent.";
          if (!selectedEnvironment) return "Please choose an environment.";
          if (normalizedType === "one-time" && !normalizedSchedule.scheduledTime) return "Please choose a date and time.";
          if (normalizedType === "recurring" && !String(normalizedSchedule.cronExpression || "").trim()) return "Please enter a cron expression.";
          return "";
        }

        function buildScheduleSavePayload(scheduleRecord) {
          const normalizedSchedule = normalizePlaygroundScheduleRecord(scheduleRecord || buildProjectScheduleDraft(selectedProject));
          const trimmedTask = String(normalizedSchedule.task || normalizedSchedule.name || "").trim();
          const trimmedName = String(normalizedSchedule.name || "").trim();
          const normalizedType = normalizedSchedule.scheduleType === "recurring" ? "recurring" : "one-time";
          const selectedAgent = agentsById[String(normalizedSchedule.agentId || "").trim()] || null;
          const selectedEnvironment = availableBacklogEnvironments.find((environment) => environment.id === String(normalizedSchedule.environmentId || "").trim()) || null;

          return {
            normalizedSchedule,
            payload: {
              name: trimmedName || trimmedTask.slice(0, 50),
              description: typeof normalizedSchedule.description === "string" ? normalizedSchedule.description : "",
              task: trimmedTask,
              taskColor: getPlaygroundTaskColorId(normalizedSchedule.taskColor),
              agentId: selectedAgent?.id || null,
              agentName: selectedAgent?.name || "Agent",
              environmentId: selectedEnvironment?.id || "",
              environmentName: selectedEnvironment?.name || "Environment",
              appId: "runner_project_calendar",
              contextId: selectedProjectId,
              contextName: selectedProject?.name || null,
              scheduleType: normalizedType,
              scheduledTime: normalizedType === "one-time" ? normalizedSchedule.scheduledTime || null : null,
              cronExpression: normalizedType === "recurring" ? String(normalizedSchedule.cronExpression || "").trim() : null,
              timezone: String(normalizedSchedule.timezone || "").trim() || "UTC",
              enabled: normalizedSchedule.enabled !== false,
              metadata: {
                ...(normalizedSchedule.metadata && typeof normalizedSchedule.metadata === "object" ? normalizedSchedule.metadata : {}),
                taskColor: getPlaygroundTaskColorId(normalizedSchedule.taskColor),
                priority: normalizedSchedule.priority,
                taskType: normalizePlaygroundTaskType(normalizedSchedule.taskType),
                parentTaskId: normalizePlaygroundParentTaskId(normalizedSchedule.parentTaskId),
                releaseId: normalizedSchedule.releaseId || null,
                dependencyIds: normalizePlaygroundIdList(normalizedSchedule.dependencyIds),
                enabledSkills: normalizePlaygroundEnabledSkillIds(normalizedSchedule.enabledSkills),
                attachments: normalizePlaygroundTaskAttachmentList(normalizedSchedule.attachments),
                connectors: normalizePlaygroundTaskConnectorSelections(normalizedSchedule.connectors),
                comments: normalizePlaygroundTaskCommentList(normalizedSchedule.comments),
                projectId: selectedProjectId,
                projectName: selectedProject?.name || null,
                source: "runner_playground_project_calendar",
              },
            },
          };
        }

        async function persistScheduleDraft(scheduleRecord, options = {}) {
          if (!selectedProjectId) return null;

          const validationError = getScheduleDraftValidationError(scheduleRecord);
          if (validationError) {
            if (options.reportError !== false) {
              resetScheduleSaveState(validationError);
            }
            return null;
          }

          const { normalizedSchedule, payload } = buildScheduleSavePayload(scheduleRecord);
          setScheduleSaveState({
            isSaving: true,
            error: "",
          });

          try {
            const isEditing = (options.mode || scheduleEditorMode) === "edit" && normalizedSchedule?.id;
            const targetUrl = backendUrl + "/projects/" + encodeURIComponent(selectedProjectId) + "/schedules" + (isEditing ? "/" + encodeURIComponent(normalizedSchedule.id) : "");
            const response = await fetch(targetUrl, {
              method: isEditing ? "PATCH" : "POST",
              headers: requestHeaders,
              body: JSON.stringify(payload),
            });
            const data = await response.json().catch(() => ({}));
            if (!response.ok) {
              throw new Error(data?.message || data?.error || "Failed to save schedule.");
            }

            const savedSchedule = getPlaygroundScheduleResponseRecord(data) || normalizePlaygroundScheduleRecord({
              ...payload,
              id: isEditing ? normalizedSchedule.id : "",
            });
            await loadProjectSchedules(selectedProjectId);
            if (savedSchedule?.id) {
              setSelectedScheduleId(savedSchedule.id);
              setScheduleEditorMode("edit");
              setScheduleDraft(savedSchedule);
              setScheduleViewMode("setup");
            }
            scheduleEditorDirtyRef.current = false;
            resetScheduleSaveState("");
            return savedSchedule;
          } catch (error) {
            const message = error instanceof Error ? error.message : "Failed to save schedule.";
            if (options.reportError !== false) {
              resetScheduleSaveState(message);
            } else {
              setScheduleSaveState({
                isSaving: false,
                error: message,
              });
            }
            return null;
          } finally {
            setScheduleSaveState((current) => ({
              ...current,
              isSaving: false,
            }));
          }
        }

        async function flushQueuedScheduleAutosave() {
          if (scheduleAutosaveInFlightRef.current || !selectedProjectId) {
            return;
          }

          scheduleAutosaveInFlightRef.current = true;
          try {
            while (scheduleAutosaveQueuedRef.current) {
              const nextScheduleToSave = normalizePlaygroundScheduleRecord(scheduleAutosaveQueuedRef.current);
              scheduleAutosaveQueuedRef.current = null;
              if (getScheduleDraftValidationError(nextScheduleToSave)) {
                continue;
              }
              const savedSchedule = await persistScheduleDraft(nextScheduleToSave, { reportError: true });
              if (!savedSchedule) {
                break;
              }
            }
          } finally {
            scheduleAutosaveInFlightRef.current = false;
          }
        }

        function queueScheduleAutosave(scheduleRecord) {
          if (!selectedProjectId) {
            return;
          }
          scheduleAutosaveQueuedRef.current = normalizePlaygroundScheduleRecord(scheduleRecord);
          if (scheduleAutosaveTimerRef.current) {
            window.clearTimeout(scheduleAutosaveTimerRef.current);
          }
          scheduleAutosaveTimerRef.current = window.setTimeout(() => {
            scheduleAutosaveTimerRef.current = null;
            void flushQueuedScheduleAutosave();
          }, 450);
        }

        async function handleSaveSchedule() {
          await persistScheduleDraft(scheduleDraft, { reportError: true });
        }

        async function handleDeleteSchedule(scheduleId) {
          if (!selectedProjectId || !scheduleId) return;

          setScheduleSaveState((current) => ({
            ...current,
            isSaving: true,
            error: "",
          }));

          try {
            const response = await fetch(backendUrl + "/projects/" + encodeURIComponent(selectedProjectId) + "/schedules/" + encodeURIComponent(scheduleId), {
              method: "DELETE",
              headers: requestHeaders,
            });
            const data = await response.json().catch(() => ({}));
            if (!response.ok) {
              throw new Error(data?.message || data?.error || "Failed to delete schedule.");
            }
            await loadProjectSchedules(selectedProjectId);
            closeScheduleDetail();
          } catch (error) {
            resetScheduleSaveState(error instanceof Error ? error.message : "Failed to delete schedule.");
          } finally {
            setScheduleSaveState((current) => ({
              ...current,
              isSaving: false,
            }));
          }
        }

        async function handleTriggerSchedule(scheduleId) {
          if (!selectedProjectId || !scheduleId) return;

          setScheduleSaveState((current) => ({
            ...current,
            isSaving: true,
            error: "",
          }));

          try {
            const response = await fetch(backendUrl + "/projects/" + encodeURIComponent(selectedProjectId) + "/schedules/" + encodeURIComponent(scheduleId) + "/trigger", {
              method: "POST",
              headers: requestHeaders,
            });
            const data = await response.json().catch(() => ({}));
            if (!response.ok) {
              throw new Error(data?.message || data?.error || "Failed to trigger schedule.");
            }
            await loadProjectSchedules(selectedProjectId);
            if (data?.thread?.id && typeof onThreadStarted === "function") {
              onThreadStarted(data.thread.id);
            }
            resetScheduleSaveState("");
          } catch (error) {
            resetScheduleSaveState(error instanceof Error ? error.message : "Failed to trigger schedule.");
          } finally {
            setScheduleSaveState((current) => ({
              ...current,
              isSaving: false,
            }));
          }
        }

        async function loadProjects() {
          setProjectLoadState((current) => ({
            status: "loading",
            error: current.status === "ready" ? "" : current.error,
          }));

          try {
            const response = await fetch(backendUrl + "/projects", {
              method: "GET",
              headers: requestHeaders,
            });
            const data = await response.json().catch(() => ({}));
            if (!response.ok) {
              throw new Error(data?.message || data?.error || "Projects API unavailable.");
            }

            const nextProjects = sortPlaygroundProjectsByRecent(
              parsePlaygroundProjectListResponse(data).map((project) => applyProjectLocalNameOverride(project))
            );
            setProjects((current) =>
              sortPlaygroundProjectsByRecent(nextProjects.map((project) => {
                const existingProject = current.find((currentProject) => currentProject?.id === project.id) || null;
                return applyProjectLocalNameOverride(mergePlaygroundProjectRecords(project, existingProject) || project);
              }))
            );
            setProjectLoadState({
              status: "ready",
              error: "",
            });

            if (selectedProjectId) {
              const refreshedProject = nextProjects.find((project) => project.id === selectedProjectId) || null;
              if (!refreshedProject) {
                handleSelectProject("");
              } else {
                setSelectedProjectDetail((current) =>
                  current?.project?.id === selectedProjectId
                    ? (() => {
                        const mergedProject = applyProjectLocalNameOverride(
                          mergePlaygroundProjectRecords(refreshedProject, current.project) || refreshedProject
                        );
                        return {
                          ...current,
                          project: mergedProject,
                          summary: mergedProject.summary || current.summary,
                        };
                      })()
                    : current
                );
              }
            }
          } catch (error) {
            setProjectLoadState({
              status: "error",
              error: error instanceof Error ? error.message : "Failed to load projects from the API.",
            });
          }
        }

        async function loadProjectWorkspace(projectId) {
          if (!projectId) {
            projectWorkspaceLoadTokenRef.current = "";
            clearProjectWorkspace();
            return;
          }

          const loadToken = projectId + ":" + Date.now().toString(36) + Math.random().toString(36).slice(2);
          projectWorkspaceLoadTokenRef.current = loadToken;
          setTaskLoadState((current) => ({
            status: "loading",
            error: current.status === "ready" ? "" : current.error,
          }));

          try {
            const threadsRequestTarget = new URL(backendUrl + "/threads", window.location.origin);
            threadsRequestTarget.searchParams.set("projectId", projectId);
            threadsRequestTarget.searchParams.set("limit", "500");

            const [tasksResponse, releasesResponse, sprintsResponse, threadsResponse] = await Promise.all([
              fetch(backendUrl + buildProjectScopedPath("/tasks", projectId), {
                method: "GET",
                headers: requestHeaders,
              }),
              fetch(backendUrl + buildProjectScopedPath("/tasks/releases", projectId), {
                method: "GET",
                headers: requestHeaders,
              }),
              fetch(backendUrl + buildProjectScopedPath("/tasks/sprints", projectId), {
                method: "GET",
                headers: requestHeaders,
              }),
              fetch(threadsRequestTarget.toString(), {
                method: "GET",
                headers: requestHeaders,
              }),
            ]);

            const tasksData = await tasksResponse.json().catch(() => ({}));
            const releasesData = await releasesResponse.json().catch(() => ({}));
            const sprintsData = await sprintsResponse.json().catch(() => ({}));
            const threadsData = await threadsResponse.json().catch(() => ({}));

            if (!tasksResponse.ok || !releasesResponse.ok || !sprintsResponse.ok || !threadsResponse.ok) {
              throw new Error(
                tasksData?.message || tasksData?.error
                || releasesData?.message || releasesData?.error
                || sprintsData?.message || sprintsData?.error
                || threadsData?.message || threadsData?.error
                || "Project workspace unavailable."
              );
            }

            if (projectWorkspaceLoadTokenRef.current !== loadToken) {
              return;
            }

            const nextTasks = parsePlaygroundTaskListResponse(tasksData);
            const nextReleases = parsePlaygroundTaskReleaseListResponse(releasesData);
            const nextSprints = parsePlaygroundTaskSprintListResponse(sprintsData);
            const currentDetailProject = selectedProjectDetail?.project?.id === projectId
              ? selectedProjectDetail.project
              : null;
            const snapshotProjectRecord = selectedProjectSnapshot
              || projects.find((project) => project?.id === projectId)
              || normalizePlaygroundProjectRecord({
                id: projectId,
                name: "Project",
              });
            const fallbackProjectRecord = currentDetailProject
              ? mergePlaygroundProjectRecords(currentDetailProject, snapshotProjectRecord) || currentDetailProject
              : snapshotProjectRecord;
            const fallbackSummary = {
              ...buildEmptyPlaygroundProjectSummary(),
              ...(fallbackProjectRecord?.summary && typeof fallbackProjectRecord.summary === "object" ? fallbackProjectRecord.summary : {}),
            };
            const fallbackEnvironments = selectedProjectDetail?.project?.id === projectId && Array.isArray(selectedProjectDetail.environments)
              ? selectedProjectDetail.environments
              : [];
            const nextThreads = Array.isArray(threadsData?.data)
              ? threadsData.data.map(normalizeThreadItem)
              : Array.isArray(threadsData?.threads)
                ? threadsData.threads.map(normalizeThreadItem)
                : [];

            commitLocalProjectRecord({
              ...fallbackProjectRecord,
              summary: fallbackSummary,
            }, {
              summary: fallbackSummary,
              environments: fallbackEnvironments,
              recentThreads: nextThreads.slice(0, 10),
              threads: nextThreads,
              selectImmediately: true,
            });

            setTasks(nextTasks);
            setReleases(nextReleases);
            setSprints(nextSprints);
            syncProjectSummary(projectId, nextTasks, nextSprints, nextReleases, fallbackSummary);
            setTaskLoadState({
              status: "ready",
              error: "",
            });

            const projectDetailPromise = fetch(backendUrl + "/projects/" + encodeURIComponent(projectId), {
                method: "GET",
                headers: requestHeaders,
              })
              .then(async (response) => ({
                response,
                data: await response.json().catch(() => ({})),
              }))
              .catch((error) => ({ error }));

            void projectDetailPromise.then((projectResult) => {
              if (projectWorkspaceLoadTokenRef.current !== loadToken) {
                return;
              }
              if (projectResult?.error) {
                console.warn("Failed to refresh project detail", projectResult.error);
                return;
              }
              const projectResponse = projectResult?.response;
              const projectData = projectResult?.data || {};
              if (!projectResponse?.ok) {
                console.warn("Failed to refresh project detail", projectData?.message || projectData?.error || projectResponse?.status);
                return;
              }

              const projectRecord = getPlaygroundProjectResponseRecord(projectData, fallbackProjectRecord) || fallbackProjectRecord;
              const nextSummary = {
                ...buildEmptyPlaygroundProjectSummary(),
                ...(projectData?.summary && typeof projectData.summary === "object" ? projectData.summary : {}),
              };
              const parsedEnvironments = parsePlaygroundEnvironmentListResponse(projectData);
              const nextEnvironments = parsedEnvironments.length > 0 ? parsedEnvironments : fallbackEnvironments;
              const nextRecentThreads = Array.isArray(projectData?.recentThreads)
                ? projectData.recentThreads.map(normalizeThreadItem)
                : nextThreads.slice(0, 10);

              commitLocalProjectRecord({
                ...projectRecord,
                summary: nextSummary,
              }, {
                summary: nextSummary,
                environments: nextEnvironments,
                recentThreads: nextRecentThreads,
                threads: nextThreads,
                selectImmediately: true,
              });
              syncProjectSummary(projectId, nextTasks, nextSprints, nextReleases, nextSummary);
            });
          } catch (error) {
            if (projectWorkspaceLoadTokenRef.current !== loadToken) {
              return;
            }
            setTaskLoadState({
              status: "error",
              error: error instanceof Error ? error.message : "Failed to load project workspace.",
            });
          }
        }

        async function loadTaskDetails(taskId) {
          if (!selectedProjectId || !taskId) {
            return null;
          }

          const response = await fetch(backendUrl + "/tasks/" + encodeURIComponent(taskId), {
            method: "GET",
            headers: requestHeaders,
          });
          const data = await response.json().catch(() => ({}));
          if (!response.ok) {
            throw new Error(data?.message || data?.error || "Failed to load task details.");
          }

          const refreshedTask = getPlaygroundTaskResponseRecord(data);
          if (!refreshedTask?.id) {
            throw new Error("Task details are unavailable.");
          }

          return applyRefreshedTaskDetails(refreshedTask);
        }

