server.on("upgrade", (req, socket, head) => {
  const requestUrl = new URL(req.url || "/", `http://localhost:${port}`);
  if (requestUrl.pathname !== "/api/real/ws/vnc") {
    socket.write("HTTP/1.1 404 Not Found\r\n\r\n");
    socket.destroy();
    return;
  }

  const upstreamTarget = normalizeWebSocketTarget(requestUrl.searchParams.get("upstream"));
  if (!upstreamTarget) {
    socket.write("HTTP/1.1 400 Bad Request\r\n\r\n");
    socket.destroy();
    return;
  }

  localVncProxyWss.handleUpgrade(req, socket, head, (ws) => {
    localVncProxyWss.emit("connection", ws, req, upstreamTarget);
  });
});

server.listen(port, () => {
  console.log(`Runner demo listening at http://localhost:${port}`);
  console.log("Live React RunnerChat mounted. Real backend proxy: /api/real/threads, /api/real/threads/:threadId, /api/real/threads/:threadId/logs, and /api/real/threads/:threadId/messages");
});
